Classes.BRHeapQA:
public class BRHeapQA implements Queueable {
    public static String stage = 'queued';
    public static Integer iterations = 0;
    public static Integer heapSeen;
    public static Integer heapLoop;
    public static Integer heapNext;
    public static Integer limitSeen;
    public void execute(QueueableContext context) {
        stage = 'started';
        limitSeen = Limits.getLimitHeapSize();
        List<String> parts = new List<String>();
        String chunk = 'x'.repeat(100000);
        Integer i = 0;
        while (Limits.getHeapSize() < 20000000 && i < 400) { parts.add(chunk + i); i++; iterations = i; heapSeen = Limits.getHeapSize(); }
        stage = 'loopDone';
        heapLoop = Limits.getHeapSize();
        Integer n = parts.size();
        heapNext = Limits.getHeapSize();
        stage = 'end|n=' + n;
    }
}

